"""変更前後を交互に実HTTP測定し、拒否・回復・整合性と遅い試行も残す。"""
import json,pathlib,subprocess,time,sys
root=pathlib.Path(__file__).resolve().parents[2];p=pathlib.Path(__file__).resolve().parent
setup=json.loads((p/'setup.json').read_text())
base=['mise','exec','--','python3',str(p/'balanced120-probe.py'),'--memory','4g','--egress-bps','80000000','--waf','--waf-posting-rate','100000','--waf-posting-concurrent','256','--waf-posting-client-rate','1000','--optional-log-stats','--collect-server-log','--posting-capacity-rate','1600','--posting-capacity-seconds','5','--posting-capacity-workers','120','--posting-capacity-threads','16','--posting-capacity-fixed-count']
rows=json.loads((p/'trials.json').read_text()) if (p/'trials.json').exists() else []
def run(variant,cpu,rep,kind='fixed'):
 name=f'{kind}-{variant}-r{rep}-{cpu}cpu'; dest=p/(name+'.json')
 if any(r['name']==name for r in rows):return
 if dest.exists():raise RuntimeError('existing unregistered result '+name)
 cmd=base+['--image',setup['images'][variant]['image'],'--cpus',str(cpu),'--output',str(dest)]
 if kind=='mixed':
  cmd.remove('--posting-capacity-fixed-count')
  for flag,value in [('--posting-capacity-rate','160'),('--posting-capacity-seconds','60'),('--egress-bps','8000000000')]:cmd[cmd.index(flag)+1]=value
  cmd+=['--posting-capacity-reads','400','--posting-capacity-subject-every','4','--posting-capacity-restart']
 if '-diag' in variant:cmd+=['--collect-profiles']
 (p/'status.json').write_text(json.dumps({'stage':name,'completed':rows},indent=2))
 print('START',name,flush=True);start=time.monotonic()
 with (p/(name+'.log')).open('w') as log:
  r=subprocess.run(cmd,cwd=root,stdout=log,stderr=subprocess.STDOUT)
 row={'name':name,'kind':kind,'version':variant,'cpus':cpu,'rep':rep,'exit_code':r.returncode,'wall_s':time.monotonic()-start,'command':cmd}
 if dest.exists():
  s=json.loads(dest.read_text()); d=s['duration_with_drain_seconds'];n=s['summary']['success']
  row.update({'throughput':n/d,'cpu_ms_per_success':s['resources']['cpu_cores_average']*d*1000/max(n,1),'summary':s['summary'],'integrity':s['integrity']['ok'],'recovery':s['recovery'],'resources':s['resources'],'memory_peak_bytes':s['memory_peak_bytes']})
 rows.append(row);(p/'trials.json').write_text(json.dumps(rows,indent=2));print('DONE',name,json.dumps({k:row.get(k) for k in ['exit_code','throughput','cpu_ms_per_success','wall_s']}),flush=True)
 if r.returncode or not row.get('integrity') or row['resources']['oom_kill_delta'] or row['recovery']['success']!=100:
  raise RuntimeError('trial integrity/OOM/recovery failure, inspect '+name)
 if row['summary']['errors'] or row['summary']['skipped']:
  if kind=='mixed':print('MIXED ADMISSION FAILURE retained; continue matched comparison',flush=True)
  else:raise RuntimeError('fixed-work acceptance failure, inspect '+name)
if len(sys.argv)>1 and sys.argv[1]=='diagnostic':
 if not (p/'input-diagnostic-built').exists():
  subprocess.run(['mise','exec','--','python3',str(p/'build-diagnosis.py')],check=True)
  (p/'input-diagnostic-built').write_text('done')
 cpu=int(sys.argv[2]);rep=int(sys.argv[3]) if len(sys.argv)>3 else 1
 for v in ['before-diag','after-diag']:run(v,cpu,rep,'diagnostic')
elif len(sys.argv)>1 and sys.argv[1]=='repeat':
 cpu=int(sys.argv[2]);rep=int(sys.argv[3])
 for v in (['after','before'] if rep%2==0 else ['before','after']):run(v,cpu,rep)
elif len(sys.argv)>1 and sys.argv[1]=='mixed':
 for rep in [1,2]:
  for v in (['before','after'] if rep==1 else ['after','before']):run(v,4,rep,'mixed')
else:
 for rep in [1,2,3]:
  for cpu in ([1,2,4] if rep%2 else [4,2,1]):
   for v in (['before','after'] if rep%2 else ['after','before']):run(v,cpu,rep)
if len(sys.argv)>1 and sys.argv[1]=='diagnostic' and int(sys.argv[2])==4 and not (p/'profiles-reviewed').exists():
 (p/'profiles-ready').write_text('ready')
 print('PROFILES READY; awaiting offline analysis before mixed runs',flush=True)
 while not (p/'profiles-reviewed').exists():time.sleep(.5)
(p/'status.json').write_text(json.dumps({'stage':'complete','completed':rows},indent=2));print('RUNS COMPLETE',flush=True)

