"""悪化した条件を逆順で追加比較し、時間比較と分離した診断・混合負荷を続ける。"""
import pathlib,json,statistics,subprocess
p=pathlib.Path(__file__).resolve().parent
rows=json.loads((p/'trials.json').read_text())
comparisons=[]
regressed=set()
for cpu in [1,2,4]:
 for rep in [1,2,3]:
  pair={r['version']:r['throughput'] for r in rows if r['kind']=='fixed' and r['cpus']==cpu and r['rep']==rep}
  if pair['after']/pair['before']<.9:regressed.add(cpu)
for cpu in [1,2,4]:
 values={v:[r['throughput'] for r in rows if r['kind']=='fixed' and r['cpus']==cpu and r['version']==v and r['exit_code']==0] for v in ['before','after']}
 ratio=statistics.median(values['after'])/statistics.median(values['before'])-1
 comparisons.append({'cpu':cpu,'change':ratio});print('INITIAL',cpu,'throughput change',round(ratio*100,2),flush=True)
 if ratio<-.03 or cpu in regressed:
  subprocess.run(['python3',str(p/'run.py'),'repeat',str(cpu),'4'],check=True)
  latest=json.loads((p/'trials.json').read_text())
  values={v:[r['throughput'] for r in latest if r['kind']=='fixed' and r['cpus']==cpu and r['version']==v and r['exit_code']==0] for v in ['before','after']}
  if statistics.median(values['after'])/statistics.median(values['before'])<.97:
   subprocess.run(['python3',str(p/'run.py'),'repeat',str(cpu),'5'],check=True)
# CPU profileは時間比較から分離。4CPUと、他CPUでの悪化が3%超の条件を診断する。
for cpu in sorted({4}|regressed|{r['cpu'] for r in comparisons if r['change']<-.03}):
 subprocess.run(['python3',str(p/'run.py'),'diagnostic',str(cpu)],check=True)
subprocess.run(['python3',str(p/'run.py'),'mixed'],check=True)
print('FOLLOWUP COMPLETE',flush=True)

