"""通常負荷を動かさず、診断用profileを読んでCPU・待機の内訳を保存する。"""
import pathlib,subprocess
p=pathlib.Path(__file__).resolve().parent
for folder in sorted(p.glob('diagnostic-*.json.profiles')):
 for profile in ['cpu','mutex','block']:
  for mode in (['-top','-top -cum'] if profile=='cpu' else ['-top']):
   args=['go','tool','pprof','-nodecount=35',*mode.split(),str(folder/(profile+'.pprof'))]
   with (folder/(profile+('-cum' if 'cum' in mode else '')+'-top.txt')).open('w') as f:subprocess.run(args,stdout=f,stderr=subprocess.STDOUT,check=True)
 for focus in ['textcodec','strictjson','ed25519','zstd','flate']:
  with (folder/('cpu-focus-'+focus+'.txt')).open('w') as f:subprocess.run(['go','tool','pprof','-top','-cum','-nodecount=8','-focus='+focus,str(folder/'cpu.pprof')],stdout=f,stderr=subprocess.STDOUT,check=True)
 print(folder.name,'analyzed',flush=True)

