"""診断専用コピーにだけ同期回数・所要時間を追加する。通常版は変更しない。"""
from pathlib import Path
p=Path(__file__).resolve().parent
code='''// 隔離診断版だけで実際のSyncを維持し、同期の回数・待機時間を集計する。
package store
import("sync/atomic";"time")
type diagnosticSyncCounter struct { calls,nanos,maxNanos,errors atomic.Uint64 }
var diagnosticSyncEnabled atomic.Bool
var diagnosticSyncCounters [3]diagnosticSyncCounter
func diagnosticSync(file interface{Sync()error},kind int)error{if !diagnosticSyncEnabled.Load(){return file.Sync()};start:=time.Now();err:=file.Sync();n:=uint64(time.Since(start));c:=&diagnosticSyncCounters[kind];c.calls.Add(1);c.nanos.Add(n);for old:=c.maxNanos.Load();n>old;old=c.maxNanos.Load(){if c.maxNanos.CompareAndSwap(old,n){break}};if err!=nil{c.errors.Add(1)};return err}
func DiagnosticSyncReset(){for i:=range diagnosticSyncCounters{c:=&diagnosticSyncCounters[i];c.calls.Store(0);c.nanos.Store(0);c.maxNanos.Store(0);c.errors.Store(0)};diagnosticSyncEnabled.Store(true)}
func DiagnosticSyncSnapshot()any{diagnosticSyncEnabled.Store(false);out:=map[string]any{};for i,name:=range []string{"writer_commit","shared_thread_group","group_body_checkpoint"}{c:=&diagnosticSyncCounters[i];out[name]=map[string]uint64{"calls":c.calls.Load(),"nanos":c.nanos.Load(),"max_nanos":c.maxNanos.Load(),"errors":c.errors.Load()}};return out}
'''
for v in ['before','after']:
 src=p/(v+'-diag-source')
 (src/'internal/store/probe_sync.go').write_text(code)
 for f,replacements in {'internal/store/durable.go':[('w.file.Sync()','diagnosticSync(w.file, 0)')],'internal/store/thread_group.go':[('g.file.Sync()','diagnosticSync(g.file, 1)'),('writer.file.Sync()','diagnosticSync(writer.file, 2)')]}.items():
  q=src/f;s=q.read_text()
  for a,b in replacements:
   assert a in s;s=s.replace(a,b)
  q.write_text(s)
 q=src/'cmd/oimobbs/probe_profile.go';s=q.read_text().replace('import("encoding/json";','import("oimobbs/internal/store";"encoding/json";').replace('runtime.ReadMemStats(&before);','store.DiagnosticSyncReset();runtime.ReadMemStats(&before);').replace('raw,_:=json.MarshalIndent(out','out["store_sync"]=store.DiagnosticSyncSnapshot();raw,_:=json.MarshalIndent(out')
 q.write_text(s)
